  box.innerHTML=`<div class="result-head"><div><span class="section-kicker">EARTIFY / SEARCH RESULT</span><h3>${escapeHTML(data.first.title||query)}</h3><p class="result-summary">${escapeHTML(data.disclaimer||"Research result")}</p></div><span class="result-badge">SEARCH</span></div>${placeCard(data.first)}`;
  box.querySelectorAll(".model3d").forEach(enableModelRotation);
