 try{const response=await fetch("/api/place-search",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({place:$("#place").value.trim(),place2:$("#place2").value.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Research search failed");renderResearch(data);updateCustomWorldCard(data.first);}
